insert into public.cards (id, owner_id, data) values
('4ef70663-56d0-4ab4-aa46-260901678151', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4ef70663-56d0-4ab4-aa46-260901678151", "code": "32ER-001", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "définition"], "front": "**Fonction affine** : définition ?", "back": "Une fonction $f$ est affine s''il existe deux nombres $a$ et $b$ tels que, pour tout $x$ :\n$f(x) = ax + b$", "createdAt": 1792366290164, "updatedAt": 1792366290164, "ocrDone": true}'::jsonb),
('26cf30d7-e742-4230-a89f-fbadf4e3bb16', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "26cf30d7-e742-4230-a89f-fbadf4e3bb16", "code": "32ER-002", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "fonction linéaire", "fonction constante", "proportionnalité"], "front": "Fonction affine $f(x)=ax+b$ : que se passe-t-il si $b = 0$ ? si $a = 0$ ?", "back": "**$b = 0$** : $f(x) = ax$, fonction **linéaire** (situation de proportionnalité, droite passant par l''origine).\n**$a = 0$** : $f(x) = b$, fonction **constante** (droite horizontale).", "createdAt": 1792366290165, "updatedAt": 1792366290165, "ocrDone": true}'::jsonb),
('8b8171f0-3d09-459f-87f4-5f1ed516f4f5', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8b8171f0-3d09-459f-87f4-5f1ed516f4f5", "code": "32ER-003", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "représentation graphique", "droite"], "front": "Quelle est la représentation graphique d''une fonction affine ?", "back": "Une **droite** (non verticale).<br>Pour la tracer, deux points suffisent.<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"15\" y1=\"138\" x2=\"200\" y2=\"15\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><circle cx=\"40\" cy=\"121\" r=\"4\" fill=\"#c0392b\"/><circle cx=\"87\" cy=\"90\" r=\"4\" fill=\"#c0392b\"/><text x=\"46\" y=\"117\" font-size=\"12\" fill=\"#c0392b\">b</text><line x1=\"87\" y1=\"120\" x2=\"87\" y2=\"90\" stroke=\"#c0392b\" stroke-dasharray=\"3\"/></svg>", "createdAt": 1792366290166, "updatedAt": 1792366290166, "ocrDone": true}'::jsonb),
('93235a2d-b491-4334-ab64-c3010b7881bc', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "93235a2d-b491-4334-ab64-c3010b7881bc", "code": "32ER-004", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "ordonnée à l''origine", "intersection", "axe des ordonnées"], "front": "Fonction affine $f(x)=ax+b$ : où la droite coupe-t-elle l''**axe des ordonnées** ?", "back": "Au point $(0\\,;\\,b)$, car $f(0) = b$.<br>$b$ s''appelle l''**ordonnée à l''origine**.<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"15\" y1=\"138\" x2=\"200\" y2=\"15\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><circle cx=\"40\" cy=\"121\" r=\"4\" fill=\"#c0392b\"/><circle cx=\"87\" cy=\"90\" r=\"4\" fill=\"#c0392b\"/><text x=\"46\" y=\"117\" font-size=\"12\" fill=\"#c0392b\">b</text><line x1=\"87\" y1=\"120\" x2=\"87\" y2=\"90\" stroke=\"#c0392b\" stroke-dasharray=\"3\"/></svg>", "createdAt": 1792366290167, "updatedAt": 1792366290167, "ocrDone": true}'::jsonb),
('d2755e1e-9783-4c7a-99cf-e5968d00ff61', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d2755e1e-9783-4c7a-99cf-e5968d00ff61", "code": "32ER-005", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "racine", "intersection", "axe des abscisses", "équation"], "front": "Fonction affine $f(x)=ax+b$ ($a \\neq 0$) : où la droite coupe-t-elle l''**axe des abscisses** ?", "back": "Là où $f(x) = 0$ : $ax + b = 0 \\iff x = -\\dfrac{b}{a}$\nPoint $\\left(-\\dfrac{b}{a}\\,;\\,0\\right)$", "createdAt": 1792366290168, "updatedAt": 1792366290168, "ocrDone": true}'::jsonb),
('3e4f2cb4-fa77-474c-8f62-490d39f1fdef', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "3e4f2cb4-fa77-474c-8f62-490d39f1fdef", "code": "22ER-001", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "coefficient directeur", "pente"], "front": "Comment calculer le **coefficient directeur** $a$ d''une droite passant par $A(x_A;y_A)$ et $B(x_B;y_B)$ ?", "back": "$a = \\dfrac{y_B - y_A}{x_B - x_A} = \\dfrac{\\Delta y}{\\Delta x}$<br>(attention à ne pas inverser : $\\Delta y$ en haut)<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"15\" y1=\"138\" x2=\"200\" y2=\"15\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><line x1=\"70\" y1=\"101\" x2=\"130\" y2=\"101\" stroke=\"#c0392b\" stroke-width=\"2\"/><line x1=\"130\" y1=\"101\" x2=\"130\" y2=\"61\" stroke=\"#c0392b\" stroke-width=\"2\"/><text x=\"92\" y=\"116\" font-size=\"12\" fill=\"#c0392b\">Δx</text><text x=\"135\" y=\"85\" font-size=\"12\" fill=\"#c0392b\">Δy</text></svg>", "createdAt": 1792366290169, "updatedAt": 1792366290169, "ocrDone": true}'::jsonb),
('aec63a6d-8088-49f8-a4ba-690f8db8d999', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "aec63a6d-8088-49f8-a4ba-690f8db8d999", "code": "22ER-002", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "coefficient directeur", "lecture graphique"], "front": "Comment **lire graphiquement** le coefficient directeur d''une droite ?", "back": "Depuis un point de la droite, on avance de **1** vers la droite et on lit de combien on **monte** ($a > 0$) ou on **descend** ($a < 0$).<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"15\" y1=\"138\" x2=\"200\" y2=\"15\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><line x1=\"70\" y1=\"101\" x2=\"130\" y2=\"101\" stroke=\"#c0392b\" stroke-width=\"2\"/><line x1=\"130\" y1=\"101\" x2=\"130\" y2=\"61\" stroke=\"#c0392b\" stroke-width=\"2\"/><text x=\"92\" y=\"116\" font-size=\"12\" fill=\"#c0392b\">Δx</text><text x=\"135\" y=\"85\" font-size=\"12\" fill=\"#c0392b\">Δy</text></svg>", "createdAt": 1792366290170, "updatedAt": 1792366290170, "ocrDone": true}'::jsonb),
('1ea01f97-00d4-4e44-aaef-74a48f2b0281', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1ea01f97-00d4-4e44-aaef-74a48f2b0281", "code": "22ER-003", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "expression", "méthode"], "front": "Méthode : trouver $f(x) = ax + b$ connaissant deux points $A$ et $B$ de la droite.", "back": "1. $a = \\dfrac{y_B - y_A}{x_B - x_A}$\n2. $b = y_A - a\\,x_A$ (on remplace dans $y_A = a x_A + b$)\n3. Vérifier avec $B$.\nEx. : $A(2;5)$, $B(6;13)$ : $a = 2$, $b = 1$, $f(x) = 2x+1$.", "createdAt": 1792366290171, "updatedAt": 1792366290171, "ocrDone": true}'::jsonb),
('dfb12c21-83fd-4a88-8752-d593fb986245', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "dfb12c21-83fd-4a88-8752-d593fb986245", "code": "22ER-004", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "sens de variation", "croissante", "décroissante"], "front": "Fonction affine $f(x)=ax+b$ : **sens de variation** selon $a$ ?", "back": "$a > 0$ : $f$ **croissante**\n$a < 0$ : $f$ **décroissante**\n$a = 0$ : $f$ constante", "createdAt": 1792366290172, "updatedAt": 1792366290172, "ocrDone": true}'::jsonb),
('195fa5c5-bf1d-4d78-8caa-0b9631ac1180', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "195fa5c5-bf1d-4d78-8caa-0b9631ac1180", "code": "22ER-005", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "signe", "tableau de signes"], "front": "**Signe** de $ax + b$ (avec $a \\neq 0$) ?", "back": "Racine $x_0 = -\\dfrac{b}{a}$ ; **signe de $a$ à droite de la racine**, signe contraire à gauche.<table style=\"border-collapse:collapse;margin:8px auto\"><tr><td style=\"border:1px solid #999;padding:4px 10px\">$x$</td><td style=\"border:1px solid #999;padding:4px 10px\">$-\\infty$</td><td style=\"border:1px solid #999;padding:4px 10px\">$-\\frac{b}{a}$</td><td style=\"border:1px solid #999;padding:4px 10px\">$+\\infty$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">$ax+b$</td><td style=\"border:1px solid #999;padding:4px 10px\">signe de $-a$</td><td style=\"border:1px solid #999;padding:4px 10px\">0</td><td style=\"border:1px solid #999;padding:4px 10px\">signe de $a$</td></tr></table>", "createdAt": 1792366290173, "updatedAt": 1792366290173, "ocrDone": true}'::jsonb),
('b2f1b4c4-f65f-4a7c-875f-4813f2421828', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b2f1b4c4-f65f-4a7c-875f-4813f2421828", "code": "22ER-006", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "droites parallèles", "coefficient directeur"], "front": "Deux droites $y = ax + b$ et $y = a''x + b''$ sont **parallèles** quand… ?", "back": "… elles ont le **même coefficient directeur** : $a = a''$.", "createdAt": 1792366290174, "updatedAt": 1792366290174, "ocrDone": true}'::jsonb),
('2f97b280-28e1-42ee-b516-fdd6c9f318a5', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2f97b280-28e1-42ee-b516-fdd6c9f318a5", "code": "32ER-006", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "intersection de deux droites", "équation"], "front": "Comment trouver le point d''**intersection** des droites $y = 2x + 1$ et $y = -x + 3$ ?", "back": "On résout $2x + 1 = -x + 3$ : $3x = 2$, $x = \\dfrac{2}{3}$\npuis $y = 2 \\times \\dfrac{2}{3} + 1 = \\dfrac{7}{3}$\nPoint $\\left(\\dfrac{2}{3}\\,;\\,\\dfrac{7}{3}\\right)$", "createdAt": 1792366290175, "updatedAt": 1792366290175, "ocrDone": true}'::jsonb),
('1bf0bf99-85ec-4189-b376-92b72bb4d0ea', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1bf0bf99-85ec-4189-b376-92b72bb4d0ea", "code": "12ER-001", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "polynôme", "degré", "définition"], "front": "Qu''est-ce qu''un **polynôme** ? Son **degré** ?", "back": "Une somme de termes de la forme $a_k x^k$ ($k$ entier positif), par ex. $3x^3 - x + 7$.\nLe **degré** est la plus grande puissance de $x$ dont le coefficient n''est pas nul (ici 3).", "createdAt": 1792366290176, "updatedAt": 1792366290176, "ocrDone": true}'::jsonb),
('fe92ba4b-0d1c-410c-9cff-38eb1e816df9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "fe92ba4b-0d1c-410c-9cff-38eb1e816df9", "code": "12ER-002", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "trinôme", "définition"], "front": "Qu''est-ce qu''un **trinôme du second degré** ?", "back": "Un polynôme de degré 2 :\n$f(x) = ax^2 + bx + c$ avec **$a \\neq 0$**\n($c = f(0)$ : ordonnée à l''origine)", "createdAt": 1792366290177, "updatedAt": 1792366290177, "ocrDone": true}'::jsonb),
('985757d2-1e89-4b12-903b-8bb4c7698287', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "985757d2-1e89-4b12-903b-8bb4c7698287", "code": "22ER-007", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "second degré", "fonction carré", "parabole"], "front": "Fonction carré $x \\mapsto x^2$ : courbe et variations ?", "back": "Une **parabole** de sommet $O(0;0)$.<br>Décroissante sur $]-\\infty;0]$, croissante sur $[0;+\\infty[$, minimum 0 en 0.<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><path d=\"M60 10 Q115 190 170 10\" fill=\"none\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><circle cx=\"115\" cy=\"100\" r=\"4\" fill=\"#c0392b\"/><text x=\"121\" y=\"112\" font-size=\"12\" fill=\"#c0392b\">S</text><line x1=\"115\" y1=\"5\" x2=\"115\" y2=\"145\" stroke=\"#999\" stroke-dasharray=\"4\"/></svg>", "createdAt": 1792366290178, "updatedAt": 1792366290178, "ocrDone": true}'::jsonb),
('b56112bb-7e6d-4c19-b7e5-5575f5efda71', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b56112bb-7e6d-4c19-b7e5-5575f5efda71", "code": "12ER-003", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "parabole", "allure", "signe de a"], "front": "Allure de la courbe de $f(x) = ax^2 + bx + c$ selon le signe de $a$ ?", "back": "Une **parabole**, d''axe de symétrie vertical $x = -\\dfrac{b}{2a}$.<br>$a > 0$ : tournée vers le **haut** (minimum)<br>$a < 0$ : tournée vers le **bas** (maximum)<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><path d=\"M60 10 Q115 190 170 10\" fill=\"none\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><circle cx=\"115\" cy=\"100\" r=\"4\" fill=\"#c0392b\"/><text x=\"121\" y=\"112\" font-size=\"12\" fill=\"#c0392b\">S</text><line x1=\"115\" y1=\"5\" x2=\"115\" y2=\"145\" stroke=\"#999\" stroke-dasharray=\"4\"/></svg><svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><path d=\"M60 140 Q115 -40 170 140\" fill=\"none\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><circle cx=\"115\" cy=\"50\" r=\"4\" fill=\"#c0392b\"/><text x=\"121\" y=\"46\" font-size=\"12\" fill=\"#c0392b\">S</text><line x1=\"115\" y1=\"5\" x2=\"115\" y2=\"145\" stroke=\"#999\" stroke-dasharray=\"4\"/></svg>", "createdAt": 1792366290179, "updatedAt": 1792366290179, "ocrDone": true}'::jsonb),
('b188a7e9-fcff-4dc7-bc8e-2e121f44be78', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b188a7e9-fcff-4dc7-bc8e-2e121f44be78", "code": "12ER-004", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "racine", "définition"], "front": "Qu''est-ce qu''une **racine** d''un trinôme $f$ ? Que représente-t-elle sur la courbe ?", "back": "Un nombre $x_0$ tel que $f(x_0) = 0$.\nC''est l''abscisse d''un point où la parabole **coupe l''axe des abscisses**.", "createdAt": 1792366290180, "updatedAt": 1792366290180, "ocrDone": true}'::jsonb),
('030e6487-72e5-4cc2-afec-9f1b57aedfeb', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "030e6487-72e5-4cc2-afec-9f1b57aedfeb", "code": "12ER-005", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "discriminant", "delta"], "front": "**Discriminant** de $ax^2 + bx + c$ : formule ?", "back": "$\\Delta = b^2 - 4ac$\n(attention : avec $b = -4$, $b^2 = (-4)^2 = 16$)", "createdAt": 1792366290181, "updatedAt": 1792366290181, "ocrDone": true}'::jsonb),
('8154c25c-e8f5-4078-8b3f-ccf3fbb7624e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8154c25c-e8f5-4078-8b3f-ccf3fbb7624e", "code": "12ER-006", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "discriminant", "racines", "méthode"], "front": "Racines de $ax^2 + bx + c$ selon le signe de $\\Delta$ ?", "back": "$\\Delta > 0$ : deux racines $x_1 = \\dfrac{-b - \\sqrt{\\Delta}}{2a}$, $x_2 = \\dfrac{-b + \\sqrt{\\Delta}}{2a}$\n$\\Delta = 0$ : une racine double $x_0 = -\\dfrac{b}{2a}$\n$\\Delta < 0$ : pas de racine réelle", "createdAt": 1792366290182, "updatedAt": 1792366290182, "ocrDone": true}'::jsonb),
('b77c0d95-c0c2-4467-b9fa-7e40bb69bcf5', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b77c0d95-c0c2-4467-b9fa-7e40bb69bcf5", "code": "12ER-007", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "discriminant", "parabole", "interprétation graphique"], "front": "Que signifie le signe de $\\Delta$ sur la **courbe** ?", "back": "$\\Delta > 0$ : la parabole coupe l''axe des abscisses en **2 points**\n$\\Delta = 0$ : elle le **touche** en 1 point (le sommet)\n$\\Delta < 0$ : elle ne le coupe **pas**", "createdAt": 1792366290183, "updatedAt": 1792366290183, "ocrDone": true}'::jsonb),
('e098f3a6-28d1-49a9-bd04-40fe406f0675', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e098f3a6-28d1-49a9-bd04-40fe406f0675", "code": "12ER-008", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "somme et produit", "racines"], "front": "**Somme** et **produit** des racines $x_1$, $x_2$ de $ax^2 + bx + c$ ?", "back": "$S = x_1 + x_2 = -\\dfrac{b}{a}$\n$P = x_1 \\times x_2 = \\dfrac{c}{a}$\n(utile pour vérifier ses racines)", "createdAt": 1792366290184, "updatedAt": 1792366290184, "ocrDone": true}'::jsonb),
('686472fd-e1fe-4581-a4b1-29848a8639c9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "686472fd-e1fe-4581-a4b1-29848a8639c9", "code": "12ER-009", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "somme et produit", "racine évidente", "méthode"], "front": "Méthode **somme-produit** : trouver les racines de $x^2 - 5x + 6$ sans $\\Delta$.", "back": "On cherche deux nombres de somme $S = -\\dfrac{b}{a} = 5$ et de produit $P = \\dfrac{c}{a} = 6$ : **2 et 3**.\nAvec une racine évidente $x_1$, l''autre vaut $x_2 = \\dfrac{c}{a\\,x_1}$.", "createdAt": 1792366290185, "updatedAt": 1792366290185, "ocrDone": true}'::jsonb),
('e752d5ff-943d-4a2c-9e3b-63c0c9b7f532', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e752d5ff-943d-4a2c-9e3b-63c0c9b7f532", "code": "12ER-010", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "forme canonique", "sommet"], "front": "**Forme canonique** d''un trinôme et coordonnées du **sommet** ?", "back": "$f(x) = a(x - \\alpha)^2 + \\beta$\navec $\\alpha = -\\dfrac{b}{2a}$ et $\\beta = f(\\alpha)$\nSommet $S(\\alpha\\,;\\,\\beta)$", "createdAt": 1792366290186, "updatedAt": 1792366290186, "ocrDone": true}'::jsonb),
('fd6cf1ec-cd22-4f66-b9ed-fe1b17e26758', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "fd6cf1ec-cd22-4f66-b9ed-fe1b17e26758", "code": "12ER-011", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "forme factorisée"], "front": "**Forme factorisée** d''un trinôme (si $\\Delta \\geq 0$) ?", "back": "$f(x) = a(x - x_1)(x - x_2)$\n(si $\\Delta = 0$ : $f(x) = a(x - x_0)^2$)\nEx. : $2x^2 - 4x - 6 = 2(x+1)(x-3)$", "createdAt": 1792366290187, "updatedAt": 1792366290187, "ocrDone": true}'::jsonb),
('0969cfb0-bd2a-4965-8530-2187fa830a4a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0969cfb0-bd2a-4965-8530-2187fa830a4a", "code": "12ER-012", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "signe", "tableau de signes"], "front": "**Signe** d''un trinôme $ax^2 + bx + c$ ?", "back": "Du **signe de $a$ à l''extérieur des racines**, du signe contraire entre les racines.\nSi $\\Delta < 0$ : toujours du signe de $a$.", "createdAt": 1792366290188, "updatedAt": 1792366290188, "ocrDone": true}'::jsonb),
('eb12aed3-7b97-47e5-8a7c-dc1f4671e136', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "eb12aed3-7b97-47e5-8a7c-dc1f4671e136", "code": "12ER-013", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "dérivée"], "front": "**Dérivée** de $f(x) = ax^2 + bx + c$ ? Où s''annule-t-elle ?", "back": "$f''(x) = 2ax + b$\nElle s''annule en $x = -\\dfrac{b}{2a} = \\alpha$ : l''abscisse du **sommet**.", "createdAt": 1792366290189, "updatedAt": 1792366290189, "ocrDone": true}'::jsonb),
('630e5031-d3a9-46f0-8118-d7791d19dd23', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "630e5031-d3a9-46f0-8118-d7791d19dd23", "code": "12ER-014", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "tableau de variation", "dérivée"], "front": "**Tableau de variation** de $f(x) = ax^2 + bx + c$ avec $a > 0$ ?", "back": "<table style=\"border-collapse:collapse;margin:8px auto\"><tr><td style=\"border:1px solid #999;padding:4px 10px\">$x$</td><td style=\"border:1px solid #999;padding:4px 10px\">$-\\infty$</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\alpha = -\\frac{b}{2a}$</td><td style=\"border:1px solid #999;padding:4px 10px\">$+\\infty$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">$f''(x)$</td><td style=\"border:1px solid #999;padding:4px 10px\">−</td><td style=\"border:1px solid #999;padding:4px 10px\">0</td><td style=\"border:1px solid #999;padding:4px 10px\">+</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">$f$</td><td style=\"border:1px solid #999;padding:4px 10px\">↘</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\beta$ (minimum)</td><td style=\"border:1px solid #999;padding:4px 10px\">↗</td></tr></table>Avec $a < 0$ : $+$ puis $-$, $f$ croissante puis décroissante, **maximum** $\\beta$.", "createdAt": 1792366290190, "updatedAt": 1792366290190, "ocrDone": true}'::jsonb),
('b805894d-de71-43b2-9555-af50548bec20', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b805894d-de71-43b2-9555-af50548bec20", "code": "12ER-015", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "extremum", "maximum", "minimum"], "front": "**Extremum** d''un trinôme : lequel, où, combien ?", "back": "Atteint au sommet, en $x = \\alpha = -\\dfrac{b}{2a}$ ; il vaut $\\beta = f(\\alpha)$.\n$a > 0$ : **minimum** ; $a < 0$ : **maximum**.\nEx. : $g(x) = -2x^2 + 8x$ : maximum $g(2) = 8$.", "createdAt": 1792366290191, "updatedAt": 1792366290191, "ocrDone": true}'::jsonb),
('7d5375ee-d4ed-4f15-b1dd-00027abd90fa', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7d5375ee-d4ed-4f15-b1dd-00027abd90fa", "code": "12ER-016", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "second degré", "méthode", "étude complète"], "front": "Méthode : **étudier complètement** un trinôme.", "back": "1. Identifier $a$, $b$, $c$ (signes !)\n2. $\\Delta$, puis les racines\n3. Sommet : $\\alpha = -\\dfrac{b}{2a}$, $\\beta = f(\\alpha)$\n4. Tableaux de variation et de signes\n5. Contrôler à la calculatrice ($S$ et $P$ des racines)", "createdAt": 1792366290192, "updatedAt": 1792366290192, "ocrDone": true}'::jsonb),
('c4b59301-437d-4345-99bb-030ed76c6af5', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c4b59301-437d-4345-99bb-030ed76c6af5", "code": "02ER-001", "origin": "ER", "subject": "Physique-Chimie", "level": "Tle", "theme": "Mouvement", "tags": ["Tle", "Mouvement", "second degré", "chute libre", "application", "temps de vol", "racine"], "front": "Objet lancé verticalement : $z(t) = -\\dfrac{1}{2}g\\,t^2 + v_0\\,t + z_0$. Comment trouver le **temps de vol** ?", "back": "C''est l''instant où l''objet touche le sol : la **racine positive** de $z(t) = 0$ (trinôme en $t$, $a = -\\dfrac{g}{2}$).\nSi $z_0 = 0$ : $t\\left(v_0 - \\dfrac{g}{2}t\\right) = 0$, d''où $t_{vol} = \\dfrac{2v_0}{g}$.", "createdAt": 1792366290193, "updatedAt": 1792366290193, "ocrDone": true}'::jsonb),
('2e30d2b0-c833-4503-b2a7-aba98c6ef1b7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2e30d2b0-c833-4503-b2a7-aba98c6ef1b7", "code": "02ER-002", "origin": "ER", "subject": "Physique-Chimie", "level": "Tle", "theme": "Mouvement", "tags": ["Tle", "Mouvement", "second degré", "chute libre", "application", "portée", "trajectoire", "racine"], "front": "Trajectoire $y(x) = -\\dfrac{g}{2v_0^2\\cos^2\\alpha}\\,x^2 + x\\tan\\alpha$ : comment trouver la **portée** ?", "back": "C''est la **racine non nulle** de $y(x) = 0$ (ici l''abscisse est une distance : on parle de portée, pas de temps de vol).<br>$x_P = \\dfrac{v_0^2 \\sin(2\\alpha)}{g}$, maximale pour $\\alpha = 45°$.<svg viewBox=\"0 0 230 150\" width=\"230\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"220\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><path d=\"M40 120 Q120 -40 200 120\" fill=\"none\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><line x1=\"120\" y1=\"40\" x2=\"120\" y2=\"120\" stroke=\"#c0392b\" stroke-dasharray=\"3\"/><text x=\"124\" y=\"85\" font-size=\"12\" fill=\"#c0392b\">flèche</text><text x=\"105\" y=\"138\" font-size=\"12\" fill=\"#c0392b\">portée</text><line x1=\"40\" y1=\"128\" x2=\"200\" y2=\"128\" stroke=\"#c0392b\"/></svg>", "createdAt": 1792366290194, "updatedAt": 1792366290194, "ocrDone": true}'::jsonb),
('76c41885-2f78-4f5b-b354-a0f9d8273013', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "76c41885-2f78-4f5b-b354-a0f9d8273013", "code": "02ER-003", "origin": "ER", "subject": "Physique-Chimie", "level": "Tle", "theme": "Mouvement", "tags": ["Tle", "Mouvement", "second degré", "chute libre", "application", "flèche", "sommet", "maximum"], "front": "Qu''est-ce que la **flèche** d''une trajectoire parabolique ? Comment la calculer ?", "back": "La **hauteur maximale** atteinte : l''ordonnée $\\beta$ du **sommet** de la parabole, atteint en $\\alpha = -\\dfrac{b}{2a}$ (là où la dérivée s''annule).<br>Par symétrie, le sommet est au milieu des deux racines (à mi-portée).<svg viewBox=\"0 0 230 150\" width=\"230\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"120\" x2=\"220\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><path d=\"M40 120 Q120 -40 200 120\" fill=\"none\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><line x1=\"120\" y1=\"40\" x2=\"120\" y2=\"120\" stroke=\"#c0392b\" stroke-dasharray=\"3\"/><text x=\"124\" y=\"85\" font-size=\"12\" fill=\"#c0392b\">flèche</text><text x=\"105\" y=\"138\" font-size=\"12\" fill=\"#c0392b\">portée</text><line x1=\"40\" y1=\"128\" x2=\"200\" y2=\"128\" stroke=\"#c0392b\"/></svg>À ne pas confondre avec la flèche d''une poutre en RDM (sa déformation).", "createdAt": 1792366290195, "updatedAt": 1792366290195, "ocrDone": true}'::jsonb);
